def stirling_second_kind(n, k, p):
    S = [[0] * (k + 1) for _ in range(n + 1)]
    S[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            S[i][j] = (j * S[i - 1][j] + S[i - 1][j - 1]) % p
    return S[n][k]

def permutations_with_runs(n, k, p):
    if k == 1:
        return 0
    total_permutations = factorial(n) % p
    for r in range(k + 1, n + 1):
        sign = (-1) ** (r - k)
        stirling = stirling_second_kind(n, r, p)
        total_permutations = (total_permutations + sign * stirling * factorial(r) % p) % p
    return total_permutations

